<script>
    window.subjectTable = function (endpoint, initialRows, initialMeta, initialSort, initialDirection) {
        return { endpoint, rows: (initialRows || []).map(subject => ({ ...subject, archiving: false, rowError: '' })), meta: initialMeta || { current_page: 1, last_page: 1, total: 0, from: null, to: null }, search: @js($search), status: @js($status), sort: initialSort || 'created_at', direction: initialDirection || 'desc', loading: false, error: '', request: null,
