            syncUrl(push = false) { const url = new URL(window.location.href); const params = url.searchParams; this.search ? params.set('search', this.search) : params.delete('search'); this.status ? params.set('status', this.status) : params.delete('status'); this.sort !== 'created_at' ? params.set('sort', this.sort) : params.delete('sort'); this.direction !== 'desc' ? params.set('direction', this.direction) : params.delete('direction'); this.meta.current_page > 1 ? params.set('page', this.meta.current_page) : params.delete('page'); window.history[push ? 'pushState' : 'replaceState']({}, '', url); },
            hasFilters() { return this.search || this.status; }, clearFilters() { this.search = ''; this.status = ''; this.load(1, true); }, sortIcon(field) { return this.sort === field ? (this.direction === 'asc' ? 'â–²' : 'â–¼') : 'â†•'; }, sortBy(field) { if (this.sort === field) this.direction = this.direction === 'asc' ? 'desc' : 'asc'; else { this.sort = field; this.direction = 'asc'; } this.load(1, true); },
            async load(page, push = false) { page = Math.max(1, page || 1); if (this.request) this.request.abort(); this.request = new AbortController(); const params = new URLSearchParams({ page, sort: this.sort, direction: this.direction }); if (this.search) params.set('search', this.search); if (this.status) params.set('status', this.status); this.loading = true; this.error = ''; try { const response = await fetch(this.endpoint + '?' + params.toString(), { headers: { Accept: 'application/json' }, signal: this.request.signal }); if (!response.ok) throw new Error('Subject search failed'); const payload = await response.json(); this.rows = (payload.data || []).map(subject => ({ ...subject, archiving: false, rowError: '' })); this.meta = payload.meta; this.syncUrl(push); } catch (error) { if (error.name !== 'AbortError') this.error = 'Subjects could not be loaded. Try again.'; } finally { this.loading = false; } },
